  /** changmen API 根（空 = 浏览器同源） */
  apiBase?: string;
  /** 登录 JWT；有则走服务端直连 CLOB L1（推荐生产） */
  authToken?: string;
}

export interface PolymarketDerivedCredentials {
  signerAddress: string;
